dark-tower-matter.adjoint-norm:
"""dark-tower-matter.adjoint-norm: exact checks, as polynomial identities.

The six causal towers (1,2), (2,1), (1,3), (3,1), (1,4), (4,1), with time direction e_t (the generator
of the minority sign). The adjoint is x^dag = e_t rev(x) e_t^-1. A primitive idempotent f of the even
subalgebra Cl^0(V) is built greedily from commuting even blades of square +1 (f = prod (1 + e_T)/2, each
factor lowering dim Cl^0 f); S = Cl^0(V) f with an exact basis, the corner f Cl^0 f with an exact basis
(the field, premise: the imported Clifford structure, its (iii)). j(psi) = <psi e_t rev(psi)>_1.
A small polynomial ring over Q (dict of exponent tuples) is used as the coefficient ring of GA.mul, so
each identity below holds for every value of the coordinates, not on samples.
(i) e_K e_K^dag = Q(e_t)^|K| for every basis blade; = 1 on even blades; for a general even x with
symbolic coordinates, <x x^dag>_0 is the sum of the squares of the coordinates.
(ii) f^dag = f; for x in f Cl^0 f with symbolic coordinates, x^dag x = x x^dag = N(x) f with
N(x) = 2 <x x^dag>_0, and N is a positive multiple of the sum of squares of x's coordinates in the
corner basis (so N(x) = 0 only at x = 0).
(iii) j(psi x) = N(x) j(psi) for symbolic psi in S and x in the corner.
"""
from fractions import Fraction as F
import GA
from tp_premise import premise

CAUSAL = [(1, 2, 0), (2, 1, 2), (1, 3, 0), (3, 1, 3), (1, 4, 0), (4, 1, 4)]
# Variable layout in check_norm_law: psi takes polynomial variables PSI_FIRST_VAR.., x the c after psi's d.
PSI_FIRST_VAR = 0


class Poly(object):
    """Polynomials over Q in nv variables: {exponent tuple: Fraction}."""
    __slots__ = ("t",)

    def __init__(self, t=None):
        self.t = {k: v for k, v in (t or {}).items() if v != 0}

    @staticmethod
    def var(i, n):
        e = [0] * n
        e[i] = 1
        return Poly({tuple(e): F(1)})

    def _co(self, o):
        if isinstance(o, Poly):
            return o
        o = F(o)
        if o == 0 or not self.t:
            return Poly() if o == 0 else Poly({(): o})
        return Poly({(0,) * len(next(iter(self.t))): o})

    def __add__(self, o):
        o = self._co(o)
        if not self.t:
            return o
        if not o.t:
            return self
        r = dict(self.t)
        for k, v in o.t.items():
            r[k] = r.get(k, 0) + v
        return Poly(r)

    __radd__ = __add__

    def __neg__(self):
        return Poly({k: -v for k, v in self.t.items()})

    def __sub__(self, o):
        return self + (-self._co(o))

    def __mul__(self, o):
        if not isinstance(o, Poly):
            o = F(o)
            return Poly({k: v * o for k, v in self.t.items()}) if o != 0 else Poly()
        r = {}
        for k1, v1 in self.t.items():
            for k2, v2 in o.t.items():
                k = tuple(a + b for a, b in zip(k1, k2))
                r[k] = r.get(k, 0) + v1 * v2
        return Poly(r)

    __rmul__ = __mul__

    def __eq__(self, o):
        return (self - self._co(o)).t == {}

    def __ne__(self, o):
        return not self.__eq__(o)

    __hash__ = None


def mv_eq(x, y):
    return all((x.get(k, 0) - y.get(k, 0)) == 0 for k in set(x) | set(y))


def scal_mv(c, x):
    return {b: c * v for b, v in x.items()}


def grade(x, k):
    return {b: c for b, c in x.items() if len(b) == k}


def setup(p, q, t):
    sq = GA.sig(p, q)
    n = p + q
    ev = [b for b in GA.all_blades(n) if len(b) % 2 == 0]

    def co(x):
        return [x.get(b, F(0)) for b in ev]

    def dim_left(f):
        return GA.rank_of_vectors([co(GA.mul({b: F(1)}, f, sq)) for b in ev])
    f, d, chosen = GA.sc(1), len(ev), []
    for b in ev:
        if b and GA.mul({b: F(1)}, {b: F(1)}, sq) == {(): F(1)} and \
                all(GA.commutes({b: F(1)}, {c: F(1)}, sq) for c in chosen):
            f2 = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), {b: F(1)})), sq)
            d2 = dim_left(f2)
            if 0 < d2 < d:
                f, d, chosen = f2, d2, chosen + [b]

    def basis_of(elts):
        rows, out = [], []
        for x in elts:
            if x and GA.rank_of_vectors(rows + [co(x)]) > len(rows):
                rows.append(co(x))
                out.append(x)
        return out
    S = basis_of([GA.mul({b: F(1)}, f, sq) for b in ev])
    C = basis_of([GA.mul(GA.mul(f, {b: F(1)}, sq), f, sq) for b in ev])
    et = GA.gen(t)
    inv = {(t,): F(1) / sq[t]}

    def dag(x):
        return GA.mul(GA.mul(et, GA.reverse(x), sq), inv, sq)

    def j(psi):
        return grade(GA.mul(GA.mul(psi, et, sq), GA.reverse(psi), sq), 1)
    return dict(sq=sq, n=n, ev=ev, f=f, S=S, C=C, et=et, Qt=sq[t], dag=dag, j=j)


def sym_combo(B, offset, nv):
    out = {}
    for i, b in enumerate(B):
        a = Poly.var(offset + i, nv)
        for k, v in b.items():
            out[k] = out.get(k, F(0)) + a * v
    return {k: v for k, v in out.items() if v != 0}


def check_blade_adjoint_norms():
    premise("dark-tower-matter.imported-clifford-structure")
    ok = True
    for p, q, t in CAUSAL:
        sq = GA.sig(p, q)
        et = GA.gen(t)
        inv = {(t,): F(1) / sq[t]}
        ok = ok and sq[t] == (1 if p == 1 else -1)
        for K in GA.all_blades(p + q):
            eK = {K: F(1)}
            prod_ = GA.mul(eK, GA.mul(GA.mul(et, GA.reverse(eK), sq), inv, sq), sq)
            ok = ok and prod_ == {(): F(sq[t]) ** len(K)}
            if len(K) % 2 == 0:
                ok = ok and prod_ == {(): F(1)}
        T = setup(p, q, t)
        nv = len(T["ev"])
        x = sym_combo([{b: F(1)} for b in T["ev"]], 0, nv)
        s0 = GA.mul(x, T["dag"](x), sq).get((), Poly())
        ssq = Poly()
        for i in range(nv):
            ssq = ssq + Poly.var(i, nv) * Poly.var(i, nv)
        ok = ok and s0 == ssq
    GA.check("lem:norm(i): e_K e_K^dag = Q(e_t)^|K|, 1 on even blades; <x x^dag>_0 = sum of squares for even x "
             "(polynomial identity, six causal towers)", ok)
    return ok


def check_corner_conjugation_and_positive_norm():
    premise("dark-tower-matter.imported-clifford-structure")
    ok = True
    dims = []
    for p, q, t in CAUSAL:
        T = setup(p, q, t)
        sq, f, C, dag = T["sq"], T["f"], T["C"], T["dag"]
        c = len(C)
        dims.append(c)
        x = sym_combo(C, 0, c)
        xdx = GA.mul(dag(x), x, sq)
        xxd = GA.mul(x, dag(x), sq)
        Nx = xxd.get((), Poly()) * 2
        ok = ok and mv_eq(dag(f), f) and mv_eq(xdx, scal_mv(Nx, f)) and mv_eq(xxd, scal_mv(Nx, f))
        ssq = Poly()
        for i in range(c):
            ssq = ssq + Poly.var(i, c) * Poly.var(i, c)
        lead = Nx.t.get(tuple(2 if k == 0 else 0 for k in range(c)), F(0))
        ok = ok and lead > 0 and Nx == ssq * lead
    ok = ok and dims == [1, 1, 2, 2, 4, 4]
    GA.check("lem:norm(ii): f^dag = f; x^dag x = x x^dag = N(x) f on the corner, N a positive multiple of the sum "
             "of squares (fields R, R, C, C, H, H)", ok)
    return ok


def check_norm_law():
    premise("dark-tower-matter.imported-clifford-structure")
    ok = True
    for p, q, t in CAUSAL:
        T = setup(p, q, t)
        sq, B, C, dag, j = T["sq"], T["S"], T["C"], T["dag"], T["j"]
        d, c = len(B), len(C)
        nv = d + c
        psi = sym_combo(B, PSI_FIRST_VAR, nv)
        x = sym_combo(C, PSI_FIRST_VAR + d, nv)
        Nx = GA.mul(x, dag(x), sq).get((), Poly()) * 2
        ok = ok and mv_eq(j(GA.mul(psi, x, sq)), scal_mv(Nx, j(psi)))
        ok = ok and not mv_eq(j(psi), {})
    GA.check("lem:norm(iii): j(psi x) = N(x) j(psi) (polynomial identity, six causal towers)", ok)
    return ok

dark-tower-matter.imported-towers-their-:
"""dark-tower-matter.imported-towers-their-types: exact checks of the computable clauses.

(1) The residue p - q mod 8 is constant along (1,1) ascents: adjoining k null pairs (Gram blocks
    [[0,1],[1,0]]) to diag(+1 x p, -1 x q) gives congruence signature (p + k, q + k), for every
    (p,q) with p + q <= 6 and k = 1, 2, 3.
(2) Under the P3 rule (dimension four for even residues; for odd ones dimension three where a
    single-time signature exists there, else the single-time signatures of dimension five) the
    representatives over all signatures with 1 <= p + q <= 10 are exactly the stated ones; the
    residues with no single-time representative are 0 and 4 (sterile).
(3) The odd residues carry no orientation bit: the bit exists exactly at tower dimension 0 mod 4
    (the flag-bit theorem); every signature of an odd residue has odd dimension (checked for all
    p + q <= 10), and there the volume element is central (blade-wise, for every odd-residue
    signature with p + q <= 7), while the even-residue representatives all sit at dimension 4.
Not computable here: exact superselection (the towers interact only through the one metric).
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

NMAX = 10
SIGS = [(p, q) for p in range(NMAX + 1) for q in range(NMAX + 1) if 1 <= p + q <= NMAX]
STATED = {6: [(1, 3)], 2: [(3, 1)], 0: [(2, 2)], 4: [(0, 4), (4, 0)],
          1: [(2, 1)], 7: [(1, 2)], 3: [(4, 1)], 5: [(1, 4)]}


def res(p, q):
    return (p - q) % 8


def causal(p, q):
    return min(p, q) == 1


def representatives(r):
    if r % 2 == 0:
        return sorted(s for s in SIGS if sum(s) == 4 and res(*s) == r)
    three = [s for s in SIGS if sum(s) == 3 and res(*s) == r and causal(*s)]
    if three:
        return sorted(three)
    return sorted(s for s in SIGS if sum(s) == 5 and res(*s) == r and causal(*s))


def ascend(p, q, k):
    n = p + q
    G = [[F(0)] * (n + 2 * k) for _ in range(n + 2 * k)]
    for i in range(n):
        G[i][i] = F(1 if i < p else -1)
    for j in range(k):
        a, b = n + 2 * j, n + 2 * j + 1
        G[a][b] = G[b][a] = F(1)
    return GA.congruence_signature(G)


def check_residue_constant_along_ascents():
    premise("tower.rigidity-clock-frozen")
    premise("dark-matter.towers-are-residues-single-clock-filter")
    count = 0
    for n in range(0, 7):
        for p in range(n + 1):
            q = n - p
            for k in (1, 2, 3):
                s = ascend(p, q, k)
                assert s == (p + k, q + k, 0) and res(s[0], s[1]) == res(p, q)
                count += 1
    assert count == 84
    return True


def check_representatives_under_p3():
    premise("dark-matter.p3-nearest-dimension-representatives")
    premise("dark-matter.towers-are-residues-single-clock-filter")
    reps = {r: representatives(r) for r in range(8)}
    assert reps == STATED
    sterile = sorted(r for r in range(8) if not any(causal(*s) for s in reps[r]))
    assert sterile == [0, 4]
    return True


def check_odd_residues_carry_no_bit():
    premise("dark-matter.flag-bit-exists-exactly-tower-dimension")
    premise("dark-matter.p3-nearest-dimension-representatives")
    assert all((p + q) % 2 == 1 for p, q in SIGS if res(p, q) % 2 == 1)
    central = 0
    for n in range(1, 8, 2):
        for p in range(n + 1):
            q = n - p
            sq = GA.sig(p, q)
            w = {tuple(range(n)): F(1)}
            assert all(GA.commutes(w, GA.gen(i), sq) for i in range(n))
            central += 1
    assert central == 20
    bit = {r: all(sum(s) % 4 == 0 for s in representatives(r)) for r in range(8)}
    assert sorted(r for r in bit if bit[r]) == [0, 2, 4, 6]
    return True

dark-tower-matter.ladder:
"""dark-tower-matter.ladder: exact checks.

Setting as in T14c: causal tower V = R^(p,q), e_t of the minority sign, f = (1 + e_t e_a)/2,
S = Cl^0(V) f, field F = f Cl^0(V) f acting on the right, x^dag = e_t rev(x) e_t^-1,
j(psi) = <psi e_t rev(psi)>_1, N(x) = 2 <x x^dag>_0. A mixing U in M_n(F) acts by
psi'_i = sum_k psi_k U_ki; (U^dag)_ik = (U_ki)^dag. Built in GA.py, spinors symbolic (polynomial
ring over Q), all six causal towers (1,2), (2,1), (1,3), (3,1), (1,4), (4,1).

(1) F-unitary mixings preserve the total momentum, as a polynomial identity in the spinors'
    coordinates: for every unit u of F (the basis f e_K f) the rotation [[c f, -s u^dag],
    [s u, c f]] with (c, s) = (3/5, 4/5) and the phase diag(u, f) (n = 2), and a 3 x 3 signed
    permutation through u (n = 3); each satisfies U U^dag = 1, computed.
(2) Only unitary mixings do: two non-unitary mixings (diag(2f, f) and the shear [[f, f], [0, f]])
    change the momentum. The proof's core is checked: j(psi a) = N(a) j(psi) on samples
    (Lemma adjoint-norm (iii)), and the polarisation step is computed: the linear map from
    Hermitian X in M_2(F) to the quadratic form a -> sum_kl 2 <a_k X_kl a_l^dag>_0 on F^2 is
    injective (rank on sample rows a equals dim Herm_2(F) = 2 + dim F), so preserving every
    momentum forces U U^dag - 1 = 0.
(3) The groups: on F the adjoint is an anti-involution whose fixed space is R f, so the
    momentum-preserving Lie algebra {X : X + X^dag = 0} in M_n(F) has dimension
    n (dim F - 1) + dim F n(n-1)/2, which for n = 1, 2, 3 equals dim o(n), u(n), sp(n) exactly
    when dim F = 1, 2, 4: O(n) in the three-dimensional towers, U(n) in this tower and the
    mirror, Sp(n) in the five-dimensional towers.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


class Poly(object):
    """Polynomials over Q in nv variables: {exponent tuple: Fraction}."""
    __slots__ = ('t',)

    def __init__(self, t=None):
        self.t = {k: v for k, v in (t or {}).items() if v != 0}

    @staticmethod
    def var(i, n):
        e = [0] * n
        e[i] = 1
        return Poly({tuple(e): F(1)})

    def _co(self, o):
        if isinstance(o, Poly):
            return o
        o = F(o)
        if o == 0:
            return Poly()
        n = len(next(iter(self.t))) if self.t else 0
        return Poly({(0,) * n: o})

    def __add__(self, o):
        o = self._co(o)
        r = dict(self.t)
        for k, v in o.t.items():
            r[k] = r.get(k, 0) + v
        return Poly(r)

    __radd__ = __add__

    def __neg__(self):
        return Poly({k: -v for k, v in self.t.items()})

    def __sub__(self, o):
        return self + (-self._co(o))

    def __rsub__(self, o):
        return self._co(o) + (-self)

    def __mul__(self, o):
        if not isinstance(o, Poly):
            o = F(o)
            return Poly({k: v * o for k, v in self.t.items()}) if o != 0 else Poly()
        r = {}
        for k1, v1 in self.t.items():
            for k2, v2 in o.t.items():
                k = tuple(a + b for a, b in zip(k1, k2))
                r[k] = r.get(k, 0) + v1 * v2
        return Poly(r)

    __rmul__ = __mul__

    def __eq__(self, o):
        return (self - self._co(o)).t == {}

    def __ne__(self, o):
        return not self.__eq__(o)

    def __hash__(self):
        return id(self)


def mv_eq(x, y):
    keys = set(x) | set(y)
    return all((x.get(k, 0) - y.get(k, 0)) == 0 for k in keys)


def grade(x, k):
    return {b: c for b, c in x.items() if len(b) == k}


# the six causal towers: (p, q, index of e_t, index of the space direction e_a)
CAUSAL = [(1, 2, 0, 1), (2, 1, 2, 0), (1, 3, 0, 1), (3, 1, 3, 0), (1, 4, 0, 1), (4, 1, 4, 0)]
ROT = (F(3, 5), F(4, 5))
A_SAMPLES = [[F(1), F(2), F(-1), F(1, 2)], [F(0), F(1), F(3), F(-2)], [F(2), F(-1), F(1), F(1)],
             [F(1, 3), F(0), F(-2), F(1)], [F(-1), F(1), F(0), F(2)], [F(1), F(1), F(1), F(-1)],
             [F(2), F(0), F(1), F(3)], [F(0), F(-1), F(2), F(1)]]


def tower(p, q, t, a):
    S = GA.sig(p, q)
    n = p + q
    ev = [b for b in GA.all_blades(n) if len(b) % 2 == 0]
    f = GA.add(GA.sc(F(1, 2)), GA.scal(F(1, 2), GA.mul(GA.gen(t), GA.gen(a), S)))

    def basis_of(xs):
        vecs, B = [], []
        for x in xs:
            v = [x.get(b, F(0)) for b in ev]
            if any(v) and GA.rank_of_vectors(vecs + [v]) > len(vecs):
                vecs.append(v)
                B.append(x)
        return B
    B = basis_of([GA.mul({K: F(1)}, f, S) for K in ev])
    C = basis_of([GA.mul(GA.mul(f, {K: F(1)}, S), f, S) for K in ev])
    et = GA.gen(t)
    inv = GA.scal(F(1, S[t]), et)

    def dag(x):
        return GA.mul(GA.mul(et, GA.reverse(x), S), inv, S)

    def j(psi):
        return grade(GA.mul(GA.mul(psi, et, S), GA.reverse(psi), S), 1)

    def N(x):
        return GA.mul(x, dag(x), S).get((), F(0)) * 2
    return dict(S=S, n=n, f=f, ev=ev, B=B, C=C, dag=dag, j=j, N=N)


def sym(B, offset, nv):
    out = {}
    for i, b in enumerate(B):
        a = Poly.var(offset + i, nv)
        for k, v in b.items():
            out[k] = out.get(k, F(0)) + a * v
    return {k: v for k, v in out.items() if v != 0}


def mix(psis, U, S):
    n = len(psis)
    return [GA.add(*[GA.mul(psis[k], U[k][i], S) for k in range(n)]) for i in range(n)]


def total(psis, j):
    return GA.add(*[j(ps) for ps in psis])


def is_unitary(U, T):
    S, f, dag = T['S'], T['f'], T['dag']
    n = len(U)
    for k in range(n):
        for l in range(n):
            s = GA.add(*[GA.mul(U[k][i], dag(U[l][i]), S) for i in range(n)])
            if not GA.eq(s, f if k == l else {}):
                return False
    return True


def check_unitary_mixings_preserve_momentum():
    premise("dark-tower-matter.adjoint-norm")
    premise("dark-tower-matter.constituents-field")
    count = 0
    for (p, q, t, a) in CAUSAL:
        T = tower(p, q, t, a)
        S, f, C, dag, j = T['S'], T['f'], T['C'], T['dag'], T['j']
        d = len(T['B'])
        psis2 = [sym(T['B'], 0, 2 * d), sym(T['B'], d, 2 * d)]
        P2 = total(psis2, j)
        cs, sn = ROT
        for u in C:
            rot = [[GA.scal(cs, f), GA.scal(-sn, dag(u))], [GA.scal(sn, u), GA.scal(cs, f)]]
            phase = [[u, {}], [{}, f]]
            for U in (rot, phase):
                assert is_unitary(U, T)
                assert mv_eq(total(mix(psis2, U, S), j), P2)
                count += 1
        # n = 3: a signed permutation through the last unit
        u = C[-1]
        psis3 = [sym(T['B'], 0, 3 * d), sym(T['B'], d, 3 * d), sym(T['B'], 2 * d, 3 * d)]
        U3 = [[{}, u, {}], [{}, {}, GA.scal(-1, f)], [f, {}, {}]]
        assert is_unitary(U3, T)
        assert mv_eq(total(mix(psis3, U3, S), j), total(psis3, j))
        count += 1
    assert count == 2 * (1 + 1 + 2 + 2 + 4 + 4) + 6
    return True


def check_only_unitary_mixings():
    premise("dark-tower-matter.adjoint-norm")
    premise("dark-tower-matter.constituents-field")
    for (p, q, t, a) in CAUSAL:
        T = tower(p, q, t, a)
        S, f, C, dag, j, N = T['S'], T['f'], T['C'], T['dag'], T['j'], T['N']
        d = len(T['B'])
        dimF = len(C)
        assert dimF == {3: 1, 4: 2, 5: 4}[T['n']]
        psis = [sym(T['B'], 0, 2 * d), sym(T['B'], d, 2 * d)]
        P = total(psis, j)
        for U in ([[GA.scal(2, f), {}], [{}, f]], [[f, f], [{}, f]]):
            assert not is_unitary(U, T)
            assert not mv_eq(total(mix(psis, U, S), j), P)
        # j(psi a) = N(a) j(psi) on a sample psi and the units and a mixed corner element
        psi = GA.add(*[GA.scal(F(k + 1, 2), b) for k, b in enumerate(T['B'])])
        amix = GA.add(*[GA.scal(F(k + 2), c) for k, c in enumerate(C)])
        for x in C + [amix]:
            assert GA.eq(j(GA.mul(psi, x, S)), GA.scal(N(x), j(psi)))
        assert N(amix) == sum(F(k + 2) ** 2 for k in range(dimF))
        # polarisation: Hermitian X in M_2(F) -> sum_kl 2 <a_k X_kl a_l^dag>_0 is injective
        herm = []
        for c in C:
            herm.append([[{}, c], [dag(c), {}]])       # off-diagonal pair
        herm.append([[f, {}], [{}, {}]])
        herm.append([[{}, {}], [{}, f]])
        rows = []
        for r, s in enumerate(A_SAMPLES):
            s2 = A_SAMPLES[(r + 3) % len(A_SAMPLES)]
            avec = [GA.add(*[GA.scal(s[i], C[i]) for i in range(dimF)]),
                    GA.add(*[GA.scal(s2[i], C[i]) for i in range(dimF)])]
            row = []
            for X in herm:
                val = F(0)
                for k in range(2):
                    for l in range(2):
                        val += GA.mul(GA.mul(avec[k], X[k][l], S), dag(avec[l]), S).get((), F(0)) * 2
                row.append(val)
            rows.append(row)
        assert GA.rank_of_vectors(rows) == dimF + 2
        assert len(herm) == dimF + 2
    return True


def check_momentum_preserving_groups():
    premise("dark-tower-matter.constituents-field")
    expected = {1: lambda n: n * (n - 1) // 2,          # o(n)
                2: lambda n: n * n,                      # u(n)
                4: lambda n: n * (2 * n + 1)}            # sp(n)
    seen = {}
    for (p, q, t, a) in CAUSAL:
        T = tower(p, q, t, a)
        S, f, C, dag = T['S'], T['f'], T['C'], T['dag']
        dimF = len(C)
        # the adjoint maps F to F and is an anti-involution: (xy)^dag = y^dag x^dag
        for x in C:
            assert GA.eq(dag(dag(x)), x)
            for y in C:
                assert GA.eq(dag(GA.mul(x, y, S)), GA.mul(dag(y), dag(x), S))
        # its fixed space in F is R f; the anti-fixed space has dimension dim F - 1
        fixed = [GA.add(c, dag(c)) for c in C]
        anti = [GA.sub(c, dag(c)) for c in C]
        ev = T['ev']
        rk = lambda xs: GA.rank_of_vectors([[x.get(b, F(0)) for b in ev] for x in xs]) if any(xs) else 0
        assert rk(fixed) == 1 and GA.eq(fixed[0], GA.scal(2, f))
        assert rk(anti) == dimF - 1
        for n in (1, 2, 3):
            dim_alg = n * rk(anti) + dimF * (n * (n - 1) // 2)
            assert dim_alg == expected[dimF](n)
        seen[(p, q)] = dimF
    assert seen == {(1, 2): 1, (2, 1): 1, (1, 3): 2, (3, 1): 2, (1, 4): 4, (4, 1): 4}
    return True

dark-tower-matter.mirror-algebra:
"""dark-tower-matter.mirror-algebra: exact checks.

(i)   phi(e_K) = (-1)^(|K|/2) e_K on even basis blades is multiplicative from Cl^0(p,q) to
      Cl^0(q,p) (the same generators with every square negated), on every pair of even blades, for
      every signature with 1 <= p + q <= 6, so in particular Cl^0(3,1) = Cl^0(1,3) and
      Cl^0(4,2) = Cl^0(2,4); phi is diagonal with entries +-1, hence bijective. Control: the naive
      map e_K -> e_K is not multiplicative between Cl^0(3,1) and Cl^0(1,3).
(ii)  phi(I4') = +I4 and phi(I6') = -I6 (pseudoscalars as even blades), and phi carries the squares
      correctly (I'^2 computed in the mirror equals phi(I')^2 computed in the reversed algebra).
(iii) The full algebras differ: a primitive idempotent of Cl(1,3) (and of Cl(3,1)) is found by a
      search over commuting blades of square +1; on the minimal left ideal the left-multiplication
      matrices of the generators are computed, and their commutant (an exact kernel) is H on an
      8-dimensional module for Cl(1,3) and R on a 4-dimensional module for Cl(3,1).
      (Fact imported-clifford-structure (iii): the commutant of a minimal left ideal is a division
      algebra; the type is computed here from the commutant's trace-free part.)
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


def phi(x):
    return {b: c * (-1) ** (len(b) // 2) for b, c in x.items()}


def even_blades(n):
    return [b for b in GA.all_blades(n) if len(b) % 2 == 0]


def multiplicative(p, q, mapping):
    Sm = GA.sig(p, q)
    So = tuple(-s for s in Sm)
    ev = even_blades(p + q)
    for a in ev:
        for b in ev:
            lhs = mapping(GA.mul({a: F(1)}, {b: F(1)}, Sm))
            rhs = GA.mul(mapping({a: F(1)}), mapping({b: F(1)}), So)
            if not GA.eq(lhs, rhs):
                return False
    return True


# ---- minimal left ideals and commutants -------------------------------------------------

def primitive_idempotent(S, n):
    blades = GA.all_blades(n)

    def dim(f):
        return GA.rank_of_vectors([[GA.mul({K: F(1)}, f, S).get(b, F(0)) for b in blades] for K in blades])
    f, d, chosen = GA.sc(1), 2 ** n, []
    for b in blades:
        if not b or GA.mul({b: F(1)}, {b: F(1)}, S) != {(): F(1)}:
            continue
        if not all(GA.commutes({b: F(1)}, {c: F(1)}, S) for c in chosen):
            continue
        f2 = GA.mul(f, GA.add(GA.sc(F(1, 2)), {b: F(1, 2)}), S)
        d2 = dim(f2)
        if 0 < d2 < d:
            f, d, chosen = f2, d2, chosen + [b]
    return f, d


def left_matrices(S, n, f, xs):
    blades = GA.all_blades(n)
    reps, vecs = [], []
    for K in blades:
        v = GA.mul({K: F(1)}, f, S)
        row = [v.get(b, F(0)) for b in blades]
        if GA.rank_of_vectors(vecs + [row]) > len(vecs):
            vecs.append(row)
            reps.append(v)
    N = len(reps)
    # pivot coordinates where the representative matrix is invertible
    piv = []
    for i, b in enumerate(blades):
        if GA.rank_of_vectors([[vecs[r][c] for c in piv + [i]] for r in range(N)]) > len(piv):
            piv.append(i)
        if len(piv) == N:
            break
    Msq = [[vecs[r][c] for r in range(N)] for c in piv]     # rows: pivot coords, cols: reps
    out = []
    for x in xs:
        cols = []
        for v in reps:
            w = GA.mul(x, v, S)
            rhs = [w.get(blades[c], F(0)) for c in piv]
            cols.append(GA.field_solve(Msq, rhs))
        out.append([[cols[j][i] for j in range(N)] for i in range(N)])
    return out, N


mm = GA.mat_mul                         # dense matrix product


def commutant(mats, N):
    rows = []
    for G in mats:
        for i in range(N):
            for j in range(N):
                r = [F(0)] * (N * N)
                for k in range(N):
                    r[i * N + k] += G[k][j]
                    r[k * N + j] -= G[i][k]
                rows.append(r)
    ker = GA.field_kernel(rows)
    return [[[v[i * N + j] for j in range(N)] for i in range(N)] for v in ker]


def division_type(basis):
    N = len(basis[0])
    if len(basis) == 1:
        return 'R'
    pure = []
    for B in basis:
        t = sum(B[i][i] for i in range(N)) / N
        P = [[B[i][j] - (t if i == j else 0) for j in range(N)] for i in range(N)]
        if any(x for r in P for x in r):
            pure.append(P)
    G = []
    for P in pure:
        row = []
        for Qm in pure:
            A, B = mm(P, Qm), mm(Qm, P)
            Sx = [[(A[i][j] + B[i][j]) / 2 for j in range(N)] for i in range(N)]
            if any(Sx[i][j] != (Sx[0][0] if i == j else 0) for i in range(N) for j in range(N)):
                return None
            row.append(Sx[0][0])
        G.append(row)
    pos, neg, zer = GA.congruence_signature(G)
    if pos == 0 and zer == 0 and GA.rank_of_vectors([[x for r in P for x in r] for P in pure]) == neg:
        return {1: 'C', 3: 'H'}.get(neg)
    return None


def check_even_isomorphism_reversed_signature():
    premise("dark-tower-matter.imported-clifford-structure")
    pairs = 0
    for n in range(1, 7):
        for p in range(n + 1):
            assert multiplicative(p, n - p, phi)
            pairs += 1
    assert pairs == 27
    # the stated instances, and phi is +-1 on every blade (bijective)
    assert multiplicative(3, 1, phi) and multiplicative(4, 2, phi)
    assert all(abs(phi({b: F(1)})[b]) == 1 for b in even_blades(6))
    # control: the identity on blades is not multiplicative between Cl0(3,1) and Cl0(1,3)
    assert not multiplicative(3, 1, lambda x: dict(x))
    return True


def check_pseudoscalars():
    I4 = {(0, 1, 2, 3): F(1)}
    I6 = {(0, 1, 2, 3, 4, 5): F(1)}
    assert GA.eq(phi(I4), I4)
    assert GA.eq(phi(I6), GA.scal(-1, I6))
    for (p, q), I in (((3, 1), I4), ((4, 2), I6)):
        Sm = GA.sig(p, q)
        So = tuple(-s for s in Sm)
        assert GA.eq(phi(GA.mul(I, I, Sm)), GA.mul(phi(I), phi(I), So))
    # the squares themselves: I4'^2 = I4^2 = -1, I6'^2 = I6^2 = -1
    assert GA.mul(I4, I4, GA.sig(3, 1)) == {(): F(-1)} and GA.mul(I4, I4, GA.sig(1, 3)) == {(): F(-1)}
    assert GA.mul(I6, I6, GA.sig(4, 2)) == {(): F(-1)} and GA.mul(I6, I6, GA.sig(2, 4)) == {(): F(-1)}
    return True


def check_full_algebras_differ():
    premise("dark-tower-matter.imported-clifford-structure")
    found = {}
    for (p, q) in ((1, 3), (3, 1)):
        S = GA.sig(p, q)
        f, d = primitive_idempotent(S, 4)
        mats, N = left_matrices(S, 4, f, [GA.gen(a) for a in range(4)])
        assert N == d
        # the generators act faithfully with the Clifford relations
        for a in range(4):
            sq = mm(mats[a], mats[a])
            assert sq == [[F(S[a]) if i == j else F(0) for j in range(N)] for i in range(N)]
        C = commutant(mats, N)
        found[(p, q)] = (N, len(C), division_type(C))
    assert found == {(1, 3): (8, 4, 'H'), (3, 1): (4, 1, 'R')}
    return True

dark-tower-matter.third-pairs-unit-five-:
"""dark-tower-matter.third-pairs-unit-five-dimensions: exact checks.

The 16-dimensional irreducible real modules of Cl(5,2) (r = 3) and Cl(2,5) (r = 5) are built as
real 16 x 16 matrices in the basis of tensor words over {I, X, Z, E} (X, Z the real symmetric Pauli
matrices, E = [[0,1],[-1,0]]); these 256 words are a basis of M_16(R), and a product of two words is
+- a word (the table is computed from the 2 x 2 matrices). Seven mutually anticommuting words with
the right squares give the generators (the Clifford relations are verified). A word commutes or
anticommutes with each generator, so commutants are spans of words, computed exactly. The module is
irreducible: its Clifford commutant is a division algebra (C for Cl(5,2), H for Cl(2,5)).

(i)   r = 3: the spin commutant (commutant of the e_0 e_a) is H; I7 lies in it, I7^2 = -1, and I7
      commutes with every vector. With Q(e_a) = Q(e_b) = +1 the third pair (e_a +- I7 e_b)/2 and two
      real pairs from hyperbolic planes obey the CAR (all relations). The nine bilinears
      I7 (v_i w_i - 1/2), v_i w_k - v_k w_i, I7 (v_i w_k + v_k w_i) close on a 9-dimensional Lie
      algebra whose centraliser in H is span{1, I7}.
(ii)  r = 3: every unit J of H anticommuting with I7 (the circle c J1 + s J2 through the basis
      units, sampled) anticommutes with every vector, sends w_i to -w_i on the real pairs and w_3
      to -wbar_3; u(3) and J generate a Lie algebra of dimension 30, not 12.
(iii) r = 5: the spin commutant H equals the Clifford commutant, its centre is R, and omega^2 = +1.
      For every sampled unit u of H (the basis units and the combinations (3/5, 4/5)) the third pair
      w_3 = (e_a + u e_b)/2, v_3 = -(e_a - u e_b)/2 with Q(e_a) = Q(e_b) = -1 joins two real pairs
      in the CAR; u(3)_u is 9-dimensional with centraliser span{1, u} in H; with a unit anticommuting
      with u it generates dimension 30. For all ordered pairs of sampled units,
      (1 - u'u) u = u' (1 - u'u), 1 - u'u is invertible unless u' = -u, where it vanishes and u' is
      reached by conjugation with a unit anticommuting with u.
"""
from fractions import Fraction as F
from itertools import product

import GA
import fock
from tp_premise import premise

# ---- the word algebra M_16(R) = M_2(R)^(x4) -----------------------------------------------
_M2 = {'I': ((1, 0), (0, 1)), 'X': ((0, 1), (1, 0)), 'Z': ((1, 0), (0, -1)), 'E': ((0, 1), (-1, 0))}


def _m2mul(A, B):
    return tuple(tuple(sum(A[i][k] * B[k][j] for k in range(2)) for j in range(2)) for i in range(2))


_TAB = {}
for _a in 'IXZE':
    for _b in 'IXZE':
        _P = _m2mul(_M2[_a], _M2[_b])
        for _c in 'IXZE':
            for _s in (1, -1):
                if _P == tuple(tuple(_s * x for x in r) for r in _M2[_c]):
                    _TAB[(_a, _b)] = (_s, _c)
L = 4
ID = 'I' * L


def wmul(u, v):
    s, out = 1, []
    for a, b in zip(u, v):
        t, c = _TAB[(a, b)]
        s *= t
        out.append(c)
    return s, ''.join(out)


def mul(x, y):
    out = {}
    for u, a in x.items():
        for v, b in y.items():
            s, w = wmul(u, v)
            out[w] = out.get(w, F(0)) + s * a * b
    return {w: c for w, c in out.items() if c != 0}


# sparse linear combinations of words: fock's helpers are key-agnostic
add = fock.madd
scal = fock.msc
sub = fock.msub


def comm(x, y):
    return sub(mul(x, y), mul(y, x))


def acomm(x, y):
    return add(mul(x, y), mul(y, x))


ONE = {ID: F(1)}


def word_sq(w):
    return wmul(w, w)[0]


def generators(p, q):
    """Seven mutually anticommuting words, p of square +1 then q of square -1 (first found)."""
    words = [''.join(t) for t in product('IXZE', repeat=L)][1:]
    need = [1] * p + [-1] * q

    def bt(ch):
        if len(ch) == len(need):
            return ch
        for w in words:
            if w not in ch and word_sq(w) == need[len(ch)] and all(wmul(w, c)[0] == -wmul(c, w)[0] for c in ch):
                r = bt(ch + [w])
                if r:
                    return r
        return None
    return [{w: F(1)} for w in bt([])]


def commutant_words(gens):
    """Span of the words commuting with every given element (each given element a +- word)."""
    out = []
    for t in product('IXZE', repeat=L):
        w = ''.join(t)
        if all(comm({w: F(1)}, g) == {} for g in gens):
            out.append({w: F(1)})
    return out


class Span(object):
    def __init__(self):
        self.piv = {}

    def add(self, x):
        r = dict(x)
        while r:
            hit = [w for w in r if w in self.piv]
            if not hit:
                break
            w = min(hit)
            c = r[w]
            r = sub(r, scal(c, self.piv[w]))
        if r:
            w = min(r)
            self.piv[w] = scal(1 / r[w], r)
            return True
        return False


def lie_closure_dim(gens):
    sp, basis = Span(), []
    for g in gens:
        if sp.add(g):
            basis.append(g)
    i = 0
    while i < len(basis):
        for j in range(i):
            c = comm(basis[i], basis[j])
            if sp.add(c):
                basis.append(c)
        i += 1
    return len(basis)


def span_dim(xs):
    sp = Span()
    return sum(1 for x in xs if sp.add(x))


def division_type(basis):
    pure = [{w: c for w, c in b.items() if w != ID} for b in basis]
    pure = [x for x in pure if x]
    if span_dim(pure) != len(basis) - 1:
        return None
    for x in pure:
        for y in pure:
            s = acomm(x, y)
            if any(w != ID for w in s):
                return None
    if not all(mul(x, x).get(ID, F(0)) < 0 for x in pure):
        return None
    if not all(acomm(x, y) == {} for i, x in enumerate(pure) for y in pure[:i]):
        return None
    return {0: 'R', 1: 'C', 3: 'H'}.get(len(pure))


def centraliser_dim(H, gens):
    """dim of {h in span H : [h, g] = 0 for all g}, as an exact kernel over the coefficients."""
    cols = [[comm(h, g) for g in gens] for h in H]
    keys = sorted({(gi, w) for c in cols for gi, x in enumerate(c) for w in x})
    rows = [[cols[k][gi].get(w, F(0)) for k in range(len(H))] for (gi, w) in keys]
    return len(GA.field_kernel(rows)) if rows else len(H)


def car(ws, vs):
    for i in range(3):
        for k in range(3):
            if acomm(ws[i], vs[k]) != (ONE if i == k else {}):
                return False
            if acomm(ws[i], ws[k]) != {} or acomm(vs[i], vs[k]) != {}:
                return False
    return True


def pair_u3(ws, vs, U):
    gens = [mul(U, sub(mul(vs[i], ws[i]), scal(F(1, 2), ONE))) for i in range(3)]
    for i in range(3):
        for k in range(i + 1, 3):
            gens.append(sub(mul(vs[i], ws[k]), mul(vs[k], ws[i])))
            gens.append(mul(U, add(mul(vs[i], ws[k]), mul(vs[k], ws[i]))))
    return gens


def setup(p, q):
    G = generators(p, q)
    S = [1] * p + [-1] * q
    for a in range(7):
        for b in range(7):
            assert acomm(G[a], G[b]) == (scal(2 * S[a], ONE) if a == b else {})
    om = ONE
    for g in G:
        om = mul(om, g)
    spin = [mul(G[0], G[a]) for a in range(1, 7)]
    H = commutant_words(spin)
    return G, S, om, H


def units(H):
    """Unit pure elements of H: the pure basis words (square -1) and their (3/5, 4/5) mixtures."""
    pure = [h for h in H if ID not in h]
    out = []
    for x in pure:
        out.extend([x, scal(-1, x)])
    for i in range(len(pure)):
        for j in range(i + 1, len(pure)):
            out.append(add(scal(F(3, 5), pure[i]), scal(F(4, 5), pure[j])))
    return [u for u in out if mul(u, u) == scal(-1, ONE)]


def check_r3_unit_and_three_pairs():
    premise("dark-tower-matter.constituents-field")
    G, S, I7, H = setup(5, 2)
    assert division_type(commutant_words(G)) == 'C'          # irreducible 16-dim module
    assert len(H) == 4 and division_type(H) == 'H'
    assert mul(I7, I7) == scal(-1, ONE)
    assert all(comm(I7, g) == {} for g in G)
    assert span_dim(H + [I7]) == 4                           # I7 lies in H
    half = F(1, 2)
    ws = [scal(half, add(G[0], G[5])), scal(half, add(G[1], G[6])), scal(half, add(G[2], mul(I7, G[3])))]
    vs = [scal(half, sub(G[0], G[5])), scal(half, sub(G[1], G[6])), scal(half, sub(G[2], mul(I7, G[3])))]
    assert S[2] == 1 and S[3] == 1
    assert mul(ws[2], ws[2]) == {}
    assert car(ws, vs)
    u3 = pair_u3(ws, vs, I7)
    assert lie_closure_dim(u3) == 9
    assert centraliser_dim(H, u3) == 2
    assert all(comm(I7, x) == {} for x in u3)               # I7 is in the centraliser
    return True


def check_r3_units_anticommuting_with_i7():
    premise("dark-tower-matter.constituents-field")
    G, S, I7, H = setup(5, 2)
    half = F(1, 2)
    ws = [scal(half, add(G[0], G[5])), scal(half, add(G[1], G[6])), scal(half, add(G[2], mul(I7, G[3])))]
    vs = [scal(half, sub(G[0], G[5])), scal(half, sub(G[1], G[6])), scal(half, sub(G[2], mul(I7, G[3])))]
    Js = [u for u in units(H) if acomm(u, I7) == {}]
    assert len(Js) == 4 + 1                                   # +-J1, +-J2 and (3 J1 + 4 J2)/5
    for J in Js:
        Jinv = scal(-1, J)
        assert all(acomm(J, g) == {} for g in G)              # acts as the grade involution
        for i in range(2):
            assert mul(mul(J, ws[i]), Jinv) == scal(-1, ws[i])
        assert mul(mul(J, ws[2]), Jinv) == scal(-1, vs[2])     # w3 -> -wbar3
    u3 = pair_u3(ws, vs, I7)
    assert lie_closure_dim(u3 + [Js[0]]) == 30
    return True


def check_r5_no_canonical_unit():
    premise("dark-tower-matter.constituents-field")
    G, S, om, H = setup(2, 5)
    assert len(H) == 4 and division_type(H) == 'H'
    assert all(comm(h, g) == {} for h in H for g in G)        # spin commutant = Clifford commutant
    assert centraliser_dim(H, H) == 1                          # centre of H is R
    assert mul(om, om) == ONE                                  # omega^2 = +1
    return True


def check_r5_third_pair_for_every_unit():
    premise("dark-tower-matter.constituents-field")
    G, S, om, H = setup(2, 5)
    half = F(1, 2)
    us = units(H)
    assert len(us) == 6 + 3
    for k, u in enumerate(us):
        assert all(comm(u, g) == {} for g in G)
        ws = [scal(half, add(G[0], G[2])), scal(half, add(G[1], G[3])), scal(half, add(G[4], mul(u, G[5])))]
        vs = [scal(half, sub(G[0], G[2])), scal(half, sub(G[1], G[3])), scal(-half, sub(G[4], mul(u, G[5])))]
        assert S[4] == -1 and S[5] == -1
        assert car(ws, vs)
        u3 = pair_u3(ws, vs, u)
        if k < 2:
            assert lie_closure_dim(u3) == 9
            assert centraliser_dim(H, u3) == 2
            v = next(x for x in us if acomm(x, u) == {})
            assert lie_closure_dim(u3 + [v]) == 30
    return True


def check_r5_units_conjugate():
    premise("dark-tower-matter.constituents-field")
    G, S, om, H = setup(2, 5)
    us = units(H)
    for u in us:
        for up in us:
            g = sub(ONE, mul(up, u))
            assert mul(g, u) == mul(up, g)
            if add(up, u) == {}:
                assert g == {}
            else:
                # g is invertible: g g^bar = |g|^2 with gbar = 1 - u u' (quaternion conjugate)
                gb = sub(ONE, mul(u, up))
                n = mul(g, gb)
                assert list(n) == [ID] and n[ID] > 0
        # u' = -u is reached by conjugation with a unit anticommuting with u
        v = next(x for x in us if acomm(x, u) == {})
        assert mul(mul(v, u), scal(-1, v)) == scal(-1, u)
    return True

dark-tower-matter.where-mass-begins:
"""dark-tower-matter.where-mass-begins: exact checks.

Setting (T14c, Definition of ideals, fields and momentum): a causal tower V = R^(p,q), min(p,q) = 1,
e_t the basis vector of the minority sign, f = (1 + e_t e_a)/2 for a space direction e_a, the
spinor ideal S = Cl^0(V) f, the adjoint x^dag = e_t rev(x) e_t^-1, the momentum
j(psi) = <psi e_t rev(psi)>_1, and the squared mass m^2(P) = Q(e_t) Q(P). Everything is built in
GA.py; spinors are symbolic (a small polynomial ring over Q as GA coefficients), so the laws are
verified as polynomial identities in the coordinates of psi (resp. psi_1, psi_2) on a basis of S,
in all six causal towers (1,2), (2,1), (1,3), (3,1), (1,4), (4,1).

(i)   n = 3, 4: rev(psi) psi = 0 identically, Q(j(psi)) = 0, and
      m^2(j(psi_1) + j(psi_2)) = 2 <x x^dag>_0 with x = rev(psi_1) psi_2; <x x^dag>_0 is the sum of
      the squares of x's blade coordinates, so the mass vanishes exactly when x = 0. The sandwich
      structure of the proof is also checked: rev(phi) phi has grades 0 and 4 only, and in
      dimension four its grade-4 part is a multiple of the pseudoscalar (commuting with e_t e_a).
(ii)  n = 5: m^2(j(psi)) = (1/2) <x x^dag>_0 with x = rev(psi) psi; the pairing is not alternating
      (rev(psi) psi is not identically zero) and a nonzero psi with rev(psi) psi = 0 exists (found
      by a search over coefficients in {-1, 0, 1}), so the zero set is a nonzero proper cone.
(iii) Every tower: Q(e_t) (j(psi) . e_t) = <psi psi^dag>_0, a sum of squares, so all momenta lie
      in one closed half-space; on rational samples of three constituents the total momentum has
      m^2 > 0 (never spacelike) and Q(e_t) (P . e_t) equals the summed squares of their coordinates.
"""
from fractions import Fraction as F
from itertools import product

import GA
from tp_premise import premise


class Poly(object):
    """Polynomials over Q in nv variables: {exponent tuple: Fraction}."""
    __slots__ = ('t',)

    def __init__(self, t=None):
        self.t = {k: v for k, v in (t or {}).items() if v != 0}

    @staticmethod
    def var(i, n):
        e = [0] * n
        e[i] = 1
        return Poly({tuple(e): F(1)})

    def _co(self, o):
        if isinstance(o, Poly):
            return o
        o = F(o)
        if o == 0:
            return Poly()
        n = len(next(iter(self.t))) if self.t else 0
        return Poly({(0,) * n: o})

    def __add__(self, o):
        o = self._co(o)
        r = dict(self.t)
        for k, v in o.t.items():
            r[k] = r.get(k, 0) + v
        return Poly(r)

    __radd__ = __add__

    def __neg__(self):
        return Poly({k: -v for k, v in self.t.items()})

    def __sub__(self, o):
        return self + (-self._co(o))

    def __rsub__(self, o):
        return self._co(o) + (-self)

    def __mul__(self, o):
        if not isinstance(o, Poly):
            o = F(o)
            return Poly({k: v * o for k, v in self.t.items()}) if o != 0 else Poly()
        r = {}
        for k1, v1 in self.t.items():
            for k2, v2 in o.t.items():
                k = tuple(a + b for a, b in zip(k1, k2))
                r[k] = r.get(k, 0) + v1 * v2
        return Poly(r)

    __rmul__ = __mul__

    def __eq__(self, o):
        return (self - self._co(o)).t == {}

    def __ne__(self, o):
        return not self.__eq__(o)

    def __hash__(self):
        return id(self)


def mv_eq(x, y):
    keys = set(x) | set(y)
    return all((x.get(k, 0) - y.get(k, 0)) == 0 for k in keys)


def is_zero_mv(x):
    return all(v == 0 for v in x.values())


def grade(x, k):
    return {b: c for b, c in x.items() if len(b) == k}


def scal_mv(c, x):
    return {b: c * v for b, v in x.items()}


# the six causal towers: (p, q, index of e_t, index of the space direction e_a)
CAUSAL = [(1, 2, 0, 1), (2, 1, 2, 0), (1, 3, 0, 1), (3, 1, 3, 0), (1, 4, 0, 1), (4, 1, 4, 0)]


def tower(p, q, t, a):
    S = GA.sig(p, q)
    n = p + q
    ev = [b for b in GA.all_blades(n) if len(b) % 2 == 0]
    f = GA.add(GA.sc(F(1, 2)), GA.scal(F(1, 2), GA.mul(GA.gen(t), GA.gen(a), S)))
    vecs, B = [], []
    for K in ev:
        x = GA.mul({K: F(1)}, f, S)
        v = [x.get(b, F(0)) for b in ev]
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            B.append(x)
    et = GA.gen(t)
    Qt = S[t]
    inv = GA.scal(F(1, Qt), et)

    def dag(x):
        return GA.mul(GA.mul(et, GA.reverse(x), S), inv, S)

    def j(psi):
        return grade(GA.mul(GA.mul(psi, et, S), GA.reverse(psi), S), 1)

    def Q(v):
        return GA.mul(v, v, S).get((), F(0))

    return dict(S=S, n=n, f=f, ev=ev, B=B, et=et, Qt=Qt, dag=dag, j=j, Q=Q)


def sym(B, offset, nv):
    out = {}
    for i, b in enumerate(B):
        a = Poly.var(offset + i, nv)
        for k, v in b.items():
            out[k] = out.get(k, F(0)) + a * v
    return {k: v for k, v in out.items() if v != 0}


def sum_sq_coords(x):
    s = Poly()
    for c in x.values():
        s = s + c * c
    return s


# rational sample spinors (coefficients on the basis of S) for the many-constituent clause
SAMPLES = [[F(1), F(-2), F(1, 3), F(0), F(3), F(-1), F(2, 5), F(1)],
           [F(-1), F(1, 2), F(2), F(-3), F(0), F(1), F(1), F(-2, 3)],
           [F(2), F(1), F(-1), F(1, 4), F(-1), F(0), F(3), F(1)]]


def check_dimensions_three_four_pair_law():
    premise("dark-tower-matter.adjoint-norm")
    for (p, q, t, a) in CAUSAL[:4]:
        T = tower(p, q, t, a)
        S, B, dag, j, Q, Qt = T['S'], T['B'], T['dag'], T['j'], T['Q'], T['Qt']
        d = len(B)
        assert d == {3: 2, 4: 4}[T['n']]
        nv = 2 * d
        psi1, psi2 = sym(B, 0, nv), sym(B, d, nv)
        # the reversion pairing is alternating and single momenta are null
        assert is_zero_mv(GA.mul(GA.reverse(psi1), psi1, S))
        assert Q(T['j'](psi1)) == 0
        # the pair law m^2 = Q(e_t) Q(P) = 2 <x x^dag>_0, x = rev(psi1) psi2
        x = GA.mul(GA.reverse(psi1), psi2, S)
        P = GA.add(j(psi1), j(psi2))
        m2 = Q(P) * Qt
        xxd0 = GA.mul(x, dag(x), S).get((), Poly())
        assert m2 == xxd0 * 2
        # <x x^dag>_0 is the sum of squares of x's coordinates: m^2 = 0 exactly when x = 0
        assert xxd0 == sum_sq_coords(x)
        assert not is_zero_mv(x)
        # the sandwich: rev(phi) phi has grades 0 and 4 only; in dimension four the 4-part is
        # a multiple of the pseudoscalar, which commutes with e_t e_a
        phi = sym([{K: F(1)} for K in T['ev']], 0, len(T['ev']))
        rp = GA.mul(GA.reverse(phi), phi, S)
        assert set(len(b) for b in rp) <= {0, 4}
        assert set(len(b) for b in rp if len(b) > 0) == ({4} if T['n'] == 4 else set())
    return True


def check_dimension_five_single_law():
    premise("dark-tower-matter.adjoint-norm")
    for (p, q, t, a) in CAUSAL[4:]:
        T = tower(p, q, t, a)
        S, B, dag, j, Q, Qt = T['S'], T['B'], T['dag'], T['j'], T['Q'], T['Qt']
        d = len(B)
        assert d == 8
        psi = sym(B, 0, d)
        x = GA.mul(GA.reverse(psi), psi, S)
        assert not is_zero_mv(x)                      # not alternating
        m2 = Q(j(psi)) * Qt
        xxd0 = GA.mul(x, dag(x), S).get((), Poly())
        assert m2 == xxd0 * F(1, 2)
        assert xxd0 == sum_sq_coords(x)
        # a nonzero massless constituent: rev(psi) psi = 0 for some psi != 0
        found = 0
        for coeffs in product((-1, 0, 1), repeat=d):
            if not any(coeffs):
                continue
            ps = GA.add(*[GA.scal(c, b) for c, b in zip(coeffs, B) if c])
            if ps and GA.mul(GA.reverse(ps), ps, S) == {}:
                found += 1
                assert Q(j(ps)) == 0                  # massless indeed
                break
        assert found == 1
    return True


def check_momenta_in_one_half_space():
    premise("dark-tower-matter.adjoint-norm")
    for (p, q, t, a) in CAUSAL:
        T = tower(p, q, t, a)
        S, B, dag, j, Q, Qt, et = T['S'], T['B'], T['dag'], T['j'], T['Q'], T['Qt'], T['et']
        d = len(B)
        psi = sym(B, 0, d)
        lhs = GA.mul(j(psi), et, S).get((), Poly()) * Qt
        rhs = GA.mul(psi, dag(psi), S).get((), Poly())
        assert lhs == rhs
        assert rhs == sum_sq_coords(psi)              # >= 0, = 0 only at psi = 0
        # three rational constituents: the total momentum is timelike or null, future side
        P, energy = {}, F(0)
        for s in SAMPLES:
            ps = GA.add(*[GA.scal(c, b) for c, b in zip(s[:d], B)])
            P = GA.add(P, j(ps))
            energy += sum(c * c for c in ps.values())
        assert Q(P) * Qt > 0
        assert GA.mul(P, et, S).get((), F(0)) * Qt == energy
    return True
